function canvasTexture(draw,size=512){const c=document.createElement('canvas');c.width=c.height=size;draw(c.getContext('2d'),size);const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;t.wrapS=t.wrapT=THREE.RepeatWrapping;return t}
let seed=2357;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}
function stoneTexture(){return canvasTexture((ctx,s)=>{ctx.fillStyle='#92948b';ctx.fillRect(0,0,s,s);for(let i=0;i<5000;i++){const a=.015+rand()*.035;ctx.fillStyle=`rgba(${rand()>.5?'40,48,42':'244,241,225'},${a})`;ctx.beginPath();ctx.ellipse(rand()*s,rand()*s,rand()*25+2,rand()*8+1,rand()*3,0,Math.PI*2);ctx.fill()}for(let j=0;j<18;j++){ctx.strokeStyle=`rgba(236,233,217,${rand()*.15+.06})`;ctx.lineWidth=rand()*2+.3;ctx.beginPath();let x=rand()*s,y=0;ctx.moveTo(x,y);while(y<s){y+=20;x+=(rand()-.5)*85;ctx.lineTo(x,y)}ctx.stroke()}ctx.strokeStyle='#c3c3b7';ctx.lineWidth=2;ctx.strokeRect(0,0,s,s)})}
function woodTexture(pattern){return canvasTexture((ctx,s)=>{ctx.fillStyle='#bdab89';ctx.fillRect(0,0,s,s);const drawPlank=(x,y,w,h,angle=0)=>{ctx.save();ctx.translate(x,y);ctx.rotate(angle);let c=rand()*20-10;ctx.fillStyle=`rgb(${186+c},${160+c},${120+c})`;ctx.fillRect(0,0,w,h);ctx.strokeStyle='rgba(107,84,51,.4)';ctx.lineWidth=1.3;ctx.strokeRect(0,0,w,h);ctx.save();ctx.beginPath();ctx.rect(1,1,w-2,h-2);ctx.clip();for(let j=0;j<32;j++){ctx.strokeStyle=`rgba(${j%3?'100,73,43':'243,221,177'},${rand()*.13+.04})`;ctx.lineWidth=rand()*1.6+.3;let yy=rand()*h;ctx.beginPath();ctx.moveTo(0,yy);for(let xx=0;xx<w;xx+=12)ctx.lineTo(xx,yy+Math.sin(xx/40+j)*2+rand()*1.2);ctx.stroke()}ctx.restore();ctx.restore()};if(pattern==='straight'){for(let y=0;y<s;y+=64)for(let x=-256;x<s;x+=256)drawPlank(x+(y%128?128:0),y,256,64)}else{const w=128,h=64;for(let col=-2;col<6;col++)for(let row=-5;row<9;row++){let x=col*w*2,y=row*h*2;ctx.save();ctx.translate(x,y);ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(w,h);ctx.lineTo(w,h*2);ctx.lineTo(0,h);ctx.closePath();ctx.save();ctx.clip();drawPlank(-80,-60,350,200,Math.PI/6);ctx.restore();ctx.strokeStyle='#9e866855';ctx.lineWidth=1.2;ctx.stroke();ctx.beginPath();ctx.moveTo(w,h);ctx.lineTo(w*2,0);ctx.lineTo(w*2,h);ctx.lineTo(w,h*2);ctx.closePath();ctx.save();ctx.clip();drawPlank(40,80,350,200,-Math.PI/6);ctx.restore();ctx.stroke();ctx.restore()}}},512)}
const stoneMap=stoneTexture(),woodChevron=woodTexture('chevron'),woodStraight=woodTexture('straight');
function floor(x,z,w,d,type='stone'){let t=(type==='wood'?woodChevron:stoneMap).clone();t.needsUpdate=true;t.repeat.set(w/(type==='wood'?2.2:.8),d/(type==='wood'?2.2:.8));const m=new THREE.MeshStandardMaterial({map:t,roughness:type==='wood'?.72:.34,color:type==='wood'?'#ffffff':'#d0d0c4'});const f=box(x,-.055,z,w,.11,d,m);if(type==='wood')woodFloors.push({mesh:f,w,d});return f}
function box(x,y,z,w,h,d,material=palette.cream,group=model,radius=0){const mesh=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);mesh.position.set(x,y,z);mesh.castShadow=true;mesh.receiveShadow=true;group.add(mesh);return mesh}
