function roundedBox(x,y,z,w,h,d,m,group=model,r=.08){const shape=new THREE.Shape();const a=w/2,b=d/2;r=Math.min(r,a,b);shape.moveTo(-a+r,-b);shape.lineTo(a-r,-b);shape.quadraticCurveTo(a,-b,a,-b+r);shape.lineTo(a,b-r);shape.quadraticCurveTo(a,b,a-r,b);shape.lineTo(-a+r,b);shape.quadraticCurveTo(-a,b,-a,b-r);shape.lineTo(-a,-b+r);shape.quadraticCurveTo(-a,-b,-a+r,-b);const g=new THREE.ExtrudeGeometry(shape,{depth:h,bevelEnabled:false,curveSegments:5});g.rotateX(-Math.PI/2);const mesh=new THREE.Mesh(g,m);mesh.position.set(x,y-h/2,z);mesh.castShadow=true;mesh.receiveShadow=true;group.add(mesh);return mesh}
function wall(x1,z1,x2,z2,{outside=false,door=null,height=2.75}={}){const horizontal=Math.abs(z2-z1)<.01,len=horizontal?Math.abs(x2-x1):Math.abs(z2-z1),mx=(x1+x2)/2,mz=(z1+z2)/2,th=.13;const segments=[];if(door){let a=horizontal?Math.min(x1,x2):Math.min(z1,z2);let b=horizontal?Math.max(x1,x2):Math.max(z1,z2);const [start,width]=door;if(start>a)segments.push([a,start]);if(start+width<b)segments.push([start+width,b]);const doorCenter=start+width/2;let lintel=box(horizontal?doorCenter:mx,2.5,horizontal?mz:doorCenter,horizontal?width:th,.5,horizontal?th:width,palette.wall);walls.push({mesh:lintel,high:2.5,lintel:true,outside});const dg=new THREE.Group();model.add(dg);const leaf=box(horizontal?start:mx,1.1,horizontal?mz:start,.055,2.2,width-.06,palette.oak,dg);if(horizontal){leaf.position.x=start+.08;leaf.position.z=mz+(width-.06)/2;}else{leaf.position.x=mx+(width-.06)/2;leaf.position.z=start+.08;leaf.rotation.y=Math.PI/2;} // doors remain open in concept view
  }else segments.push([horizontal?Math.min(x1,x2):Math.min(z1,z2),horizontal?Math.max(x1,x2):Math.max(z1,z2)]);
  segments.forEach(([a,b])=>{let px=horizontal?(a+b)/2:mx,pz=horizontal?mz:(a+b)/2,w=horizontal?b-a:th,d=horizontal?th:b-a;const m=box(px,height/2,pz,w,height,d,palette.wall);walls.push({mesh:m,high:height/2,height,outside});box(px,.065,pz,horizontal?w:th+.018,.13,horizontal?th+.018:d,palette.trim);colliders.push({x1:px-w/2-.13,x2:px+w/2+.13,z1:pz-d/2-.13,z2:pz+d/2+.13});});
}
function windowWall(x1,z1,x2,z2){const horizontal=Math.abs(z2-z1)<.01,len=horizontal?Math.abs(x2-x1):Math.abs(z2-z1),mx=(x1+x2)/2,mz=(z1+z2)/2;const glass=new THREE.MeshPhysicalMaterial({color:'#b8d5cd',transparent:true,opacity:.15,roughness:.1,metalness:.15,depthWrite:false,side:THREE.DoubleSide});box(mx,1.52,mz,horizontal?len:.035,2.05,horizontal?.035:len,glass);for(let i=0;i<=Math.ceil(len/.95);i++){const f=i/Math.ceil(len/.95);box(x1+(x2-x1)*f,1.52,z1+(z2-z1)*f,.035,2.12,.035,palette.black)}[.46,2.56].forEach(y=>box(mx,y,mz,horizontal?len:.035,.04,horizontal?.035:len,palette.black));}
