  rug(8.4,7.55,2.75,2.0,'#b8af9b');bed(8.4,7.22,1.8,palette.teal,Math.PI);wardrobe(8.55,6.16,1.3,.5);box(9.98,.28,7.5,.65,.56,2.4,palette.white);plant(9.9,8.55,.65);picture(7.0,1.64,7.52,.9,.7,Math.PI/2);
