function updateWalls(){const high=mode==='walk'||fullWalls;walls.forEach(w=>{if(w.lintel){w.mesh.visible=high;return}const h=high?w.height:(w.outside?.58:.83);w.mesh.scale.y=h/w.height;w.mesh.position.y=h/2});}
function setNight(value){night=value;$('.viewer').classList.toggle('night',night);$('#dayBtn').classList.toggle('active',!night);$('#nightBtn').classList.toggle('active',night);$('#dayBtn').setAttribute('aria-pressed',String(!night));$('#nightBtn').setAttribute('aria-pressed',String(night));$('#lightLabel').textContent=night?'温暖灯光':'柔和日光';if(!renderer)return;ambient.intensity=night?.45:2.25;sun.intensity=night?.22:3.2;fill.intensity=night?.22:1.2;warmLights.forEach(l=>l.intensity=night?15:0);scene.fog.color.set(night?'#344a4b':'#e8e9df');ground.material.color.set(night?'#405153':'#dfe2d5');renderer.toneMappingExposure=night?.95:1.1;}
function setPattern(pattern){woodFloors.forEach(({mesh,w,d})=>{const t=(pattern==='chevron'?woodChevron:woodStraight).clone();t.needsUpdate=true;t.repeat.set(w/2.2,d/2.2);mesh.material.map.dispose();mesh.material.map=t;mesh.material.needsUpdate=true});$$('[data-pattern]').forEach(b=>b.classList.toggle('active',b.dataset.pattern===pattern));$('#woodName').innerHTML=(pattern==='chevron'?'浅橡木 · 鱼骨纹砖':'浅橡木 · 直铺木纹砖')+' <span class="swatch wood"></span>';toast(pattern==='chevron'?'卧室已切换为鱼骨拼 · 拼法示意':'卧室已切换为直铺 · 拼法示意')}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function stopTour(){clearTimeout(tourTimer);tourTimer=null;$('#tourBtn').textContent='◉ 开始全屋导览'}
function selectRoom(id,fromTour=false){if(!fromTour)stopTour();selected=id;const r=roomData.find(v=>v.id===id);$$('.room-button').forEach(b=>{b.classList.toggle('active',b.dataset.room===id);b.setAttribute('aria-current',b.dataset.room===id?'true':'false')});$('#viewTitle').textContent=r.title;$('#viewDesc').textContent=r.desc;$('#viewEyebrow').textContent=id==='all'?'YOUR HOME, IN PERSPECTIVE':'A LITTLE CLOSER TO HOME';if(!camera)return;if(id==='all'){if(mode==='walk')setMode('overview',false);else frameRoom(r)}else frameRoom(r)}
function frameRoom(r){if(mode==='walk'){const p=r.eye||[3.9,1.55,5.25],t=r.look||[1.8,1.2,7];camera.position.set(...p);setWalkLook(new THREE.Vector3(...t));transition=null;}else if(mode==='plan'){animateCamera(new THREE.Vector3(r.id==='all'?5.2:r.x,20,r.id==='all'?5.1:r.z+.001),new THREE.Vector3(r.id==='all'?5.2:r.x,0,r.id==='all'?5.1:r.z),r.id==='all'?1:1.65)}else{const mobile=host.clientWidth<550;const target=new THREE.Vector3(r.id==='all'?5.1:r.x,0,r.id==='all'?5.0:r.z);const offset=r.id==='all'?new THREE.Vector3(12,13,14).multiplyScalar(Math.max(1,1.05/(host.clientWidth/host.clientHeight))):new THREE.Vector3(5.0,7,6.0);animateCamera(target.clone().add(offset),target,1)}}
function animateCamera(pos,target,zoom=1){const zoomFactor=mode==='plan'?zoom:1;transition={from:camera.position.clone(),to:pos,fromTarget:controls.target.clone(),toTarget:target,start:performance.now(),duration:window.matchMedia('(prefers-reduced-motion: reduce)').matches?0:900,fromZoom:camera.zoom,toZoom:zoomFactor};}
function setWalkLook(target){const v=target.clone().sub(camera.position).normalize();walkYaw=Math.atan2(v.x,v.z);walkPitch=Math.asin(v.y);updateWalkLook()}
function updateWalkLook(){const v=new THREE.Vector3(Math.sin(walkYaw)*Math.cos(walkPitch),Math.sin(walkPitch),Math.cos(walkYaw)*Math.cos(walkPitch));camera.lookAt(camera.position.clone().add(v));}
function setMode(value,resetSelection=true){stopTour();mode=value;$$('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));$('#walkControls').hidden=mode!=='walk';$('#gestureHint').innerHTML=mode==='walk'?'拖动环顾 <i>·</i> W A S D 移动 <i>·</i> 点击空间切换':mode==='plan'?'拖动平移 <i>·</i> 滚轮缩放':'<span>⤧</span> 拖动旋转 <i>·</i> 滚轮缩放 <i>·</i> 右键平移';if(!controls)return;camera.zoom=1;camera.fov=mode==='walk'?72:36;camera.updateProjectionMatrix();transition=null;controls.enabled=mode!=='walk';controls.enableRotate=mode==='overview';controls.mouseButtons.LEFT=mode==='plan'?THREE.MOUSE.PAN:THREE.MOUSE.ROTATE;controls.minDistance=mode==='plan'?6:3;controls.maxDistance=40;controls.minPolarAngle=mode==='plan'?0:.04;controls.maxPolarAngle=mode==='plan'?.001:Math.PI/2.02;updateWalls();frameRoom(roomData.find(r=>r.id===selected));if(mode==='walk')toast('拖动环顾，W A S D 或屏幕按钮移动；左侧可切换房间')}
function createLabels(){roomData.filter(r=>r.id!=='all').forEach(r=>{const b=document.createElement('button');b.className='room-label';b.textContent=r.name;b.onclick=()=>selectRoom(r.id);$('#labels').appendChild(b);roomLabels.push({el:b,pos:new THREE.Vector3(r.x,.1,r.z)})})}
function updateLabels(){roomLabels.forEach(({el,pos})=>{if(!labelsVisible||mode==='walk'){el.style.display='none';return}const p=pos.clone().project(camera);if(p.z>1||p.z< -1||Math.abs(p.x)>.94||Math.abs(p.y)>.9){el.style.display='none';return}el.style.display='block';el.style.left=(p.x*.5+.5)*host.clientWidth+'px';el.style.top=(-p.y*.5+.5)*host.clientHeight+'px';el.style.opacity=selected==='all'||el.textContent===roomData.find(r=>r.id===selected).name?'1':'.72'})}
function isInside(x,z){return(x>.17&&x<4.37&&z>.17&&z<9.82)||(x>4.37&&x<8.09&&z>1.65&&z<8.63)||(x>8.09&&x<9.06&&z>2.43&&z<8.63)||(x>9.06&&x<10.23&&z>3.05&&z<8.63)}
function canMove(x,z){return isInside(x,z)&&!colliders.some(c=>x>c.x1&&x<c.x2&&z>c.z1&&z<c.z2)}
function moveWalk(dt){let forward=(keys.has('w')||keys.has('arrowup')||walkMove==='forward'?1:0)-(keys.has('s')||keys.has('arrowdown')||walkMove==='back'?1:0);let side=(keys.has('d')||keys.has('arrowright')||walkMove==='right'?1:0)-(keys.has('a')||keys.has('arrowleft')||walkMove==='left'?1:0);if(!forward&&!side)return;const speed=dt*1.5/Math.max(1,Math.hypot(forward,side));const dx=(Math.sin(walkYaw)*forward-Math.cos(walkYaw)*side)*speed,dz=(Math.cos(walkYaw)*forward+Math.sin(walkYaw)*side)*speed;if(canMove(camera.position.x+dx,camera.position.z))camera.position.x+=dx;if(canMove(camera.position.x,camera.position.z+dz))camera.position.z+=dz;updateWalkLook()}
function animate(){requestAnimationFrame(animate);if(!renderer)return;const dt=Math.min(clock.getDelta(),.05);if(transition){const raw=(performance.now()-transition.start)/Math.max(1,transition.duration),t=Math.min(1,raw),ease=1-Math.pow(1-t,3);camera.position.lerpVectors(transition.from,transition.to,ease);controls.target.lerpVectors(transition.fromTarget,transition.toTarget,ease);camera.zoom=THREE.MathUtils.lerp(transition.fromZoom,transition.toZoom,ease);camera.updateProjectionMatrix();if(t===1)transition=null;}if(mode==='walk')moveWalk(dt);else controls.update();updateLabels();renderer.render(scene,camera)}
function init(){try{renderer=new THREE.WebGLRenderer({antialias:true,alpha:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(window.devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.outputColorSpace=THREE.SRGBColorSpace;host.appendChild(renderer.domElement);scene=new THREE.Scene();scene.fog=new THREE.Fog('#e8e9df',35,80);scene.add(model);camera=new THREE.PerspectiveCamera(36,1,.05,100);camera.position.set(17.1,13,19);controls=new OrbitControls(camera,renderer.domElement);controls.target.set(5.1,0,5);controls.enableDamping=true;controls.dampingFactor=.08;controls.maxPolarAngle=Math.PI/2.02;controls.minDistance=3;controls.maxDistance=40;controls.addEventListener('start',()=>{transition=null;stopTour()});ambient=new THREE.HemisphereLight('#fff9e7','#9da58e',2.25);scene.add(ambient);sun=new THREE.DirectionalLight('#fff3da',3.2);sun.position.set(-3,13,11);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-14;sun.shadow.camera.right=14;sun.shadow.camera.top=14;sun.shadow.camera.bottom=-14;sun.shadow.normalBias=.025;sun.shadow.bias=-.0002;sun.target.position.set(5,0,5);scene.add(sun,sun.target);fill=new THREE.DirectionalLight('#e0eff0',1.2);fill.position.set(12,8,-5);scene.add(fill);ground=box(5.2,-.36,5,200,.1,200,mat('#dfe2d5'),scene);ground.castShadow=false;buildHome();createLabels();const resize=()=>{const w=host.clientWidth,h=host.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix();if(mode==='overview'&&selected==='all')frameRoom(roomData[0])};new ResizeObserver(resize).observe(host);resize();setNight(false);setMode('overview');setTimeout(()=>$('#loading').classList.add('done'),350);bindCanvas();animate();window.__home={roomData,model,renderer,camera,get mode(){return mode},get selected(){return selected},get night(){return night},get fullWalls(){return fullWalls},keys,woodFloors,selectRoom,setMode,canMove};}catch(e){console.error(e);$('#loading').classList.add('done');$('#webglError').hidden=false}}
function bindCanvas(){const el=renderer.domElement;el.addEventListener('pointerdown',e=>{if(mode!=='walk')return;dragStart={x:e.clientX,y:e.clientY,yaw:walkYaw,pitch:walkPitch};el.setPointerCapture(e.pointerId)});el.addEventListener('pointermove',e=>{if(mode!=='walk'||!dragStart)return;walkYaw=dragStart.yaw-(e.clientX-dragStart.x)*.005;walkPitch=THREE.MathUtils.clamp(dragStart.pitch+(e.clientY-dragStart.y)*.004,-.85,.85);updateWalkLook()});el.addEventListener('pointerup',()=>dragStart=null);el.addEventListener('pointercancel',()=>dragStart=null);el.addEventListener('contextmenu',e=>e.preventDefault());el.addEventListener('webglcontextlost',e=>{e.preventDefault();toast('3D 连接已中断，请刷新页面恢复')});}
function zoom(amount){if(!camera)return;if(mode==='walk'){toast('室内漫游可用前进/后退按钮移动');return}stopTour();transition=null;const delta=camera.position.clone().sub(controls.target);delta.multiplyScalar(amount);delta.clampLength(controls.minDistance,controls.maxDistance);camera.position.copy(controls.target).add(delta);controls.update()}
$$('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));
$$('[data-pattern]').forEach(b=>b.onclick=()=>setPattern(b.dataset.pattern));
$('#dayBtn').onclick=()=>setNight(false);$('#nightBtn').onclick=()=>setNight(true);
$('#wallBtn').onclick=()=>{if(mode==='walk'){toast('室内漫游使用完整墙体，切回全屋 3D 可查看低墙透视');return}fullWalls=!fullWalls;$('#wallBtn').setAttribute('aria-pressed',String(fullWalls));$('#wallBtn span').textContent=fullWalls?'完整墙体':'低墙透视';updateWalls()};
$('#labelBtn').onclick=()=>{labelsVisible=!labelsVisible;$('#labelBtn').setAttribute('aria-pressed',String(labelsVisible))};
$('#zoomIn').onclick=()=>zoom(.85);$('#zoomOut').onclick=()=>zoom(1.18);$('#resetBtn').onclick=()=>{stopTour();selected='all';setMode('overview');selectRoom('all')};
$('#fullscreenBtn').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('.viewer').requestFullscreen()}catch{toast('此浏览器未允许全屏，可使用浏览器全屏功能')}};
$('#screenshotBtn').onclick=()=>{if(!renderer)return;renderer.render(scene,camera);const a=document.createElement('a');a.download=`云筑上品107-${selected}-${night?'夜间':'日间'}.png`;a.href=renderer.domElement.toDataURL('image/png');a.click();toast('当前 3D 效果图已保存')};
$('#tourBtn').onclick=()=>{if(tourTimer){stopTour();return}tourIndex=0;const steps=['living','dining','study','guest','child','master','bath','all'];function step(){const id=steps[tourIndex++];if(id==='all'){setMode('overview');selectRoom('all',true);stopTour();toast('全屋导览结束，欢迎继续自在探索');return}mode='walk';camera.fov=72;camera.updateProjectionMatrix();$$('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode==='walk'));$('#walkControls').hidden=false;$('#gestureHint').textContent='全屋导览中 · 点击空间或拖动画面可随时结束';controls.enabled=false;updateWalls();selectRoom(id,true);$('#tourBtn').textContent='◼ 结束全屋导览';tourTimer=setTimeout(step,5500)}step()};
window.addEventListener('keydown',e=>{if($('dialog[open]')||/INPUT|TEXTAREA/.test(e.target.tagName))return;const k=e.key.toLowerCase();if(mode==='walk'&&['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright'].includes(k)){e.preventDefault();stopTour();keys.add(k)}if(e.key==='Escape'&&mode==='walk')setMode('overview')});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();walkMove=null});
$$('[data-move]').forEach(b=>{b.addEventListener('pointerdown',e=>{stopTour();walkMove=b.dataset.move;b.setPointerCapture(e.pointerId);e.preventDefault()});['pointerup','pointercancel','lostpointercapture'].forEach(n=>b.addEventListener(n,()=>walkMove=null))});
const referenceData={stone:{src:'./assets/stone-swatch.svg',alt:'精装灰砖的示意材质',text:'图为程序绘制的材质示意，原始精装实拍保留在本地。公共区域保留灰色石纹砖，配合暖白墙面、浅色柜门与木色台面。照片受现场光线影响，3D 中的颜色为近似表达。'},wood:{src:'./assets/wood-swatch.svg',alt:'浅橡木色鱼骨纹砖示意',text:'图为浅橡木色与 V 形鱼骨纹的材质示意，原始样板照片保留在本地。3D 的鱼骨拼与直铺用于比较氛围；具体规格、拼角、色号和铺贴方式需与商家确认。'},layout:{src:'./assets/layout-reference.png',alt:'网上公开的云启约107平方米四房户型参考图',text:'布局参考：公开“云启 · 建筑面积约107㎡”四房两厅两卫户型图，并结合你的视频字幕：入户多功能房、U 型厨房、约5.2米阳台、两间次卧、带独卫主卧。本图不代表你家合同附图，模型尺寸、窗位和家具布置均为估算。',links:true},living:{src:'./assets/stone-swatch.svg',alt:'公共区域灰色石纹示意',text:'公共区域材质示意。原始客餐厅照片保留在本地。设计延续大方厅、浅色沙发、低矮电视柜和通透阳台的空间关系；家具为本页面的概念方案。'}};
function openReference(tab='stone'){const d=referenceData[tab];$$('[data-ref-tab]').forEach(b=>b.classList.toggle('active',b.dataset.refTab===tab));$('#referenceContent').innerHTML=`<img src="${d.src}" alt="${d.alt}"><p>${d.text}</p>${d.links?'<p><a href="https://www.sohu.com/a/1035574656_122525359" target="_blank" rel="noopener noreferrer">查看公开户型来源</a> · <a href="https://xhslink.cn/o/asOJ5JRrss" target="_blank" rel="noopener noreferrer">查看你提供的看房视频</a></p>':''}`;if(!$('#referenceDialog').open)$('#referenceDialog').showModal()}
$('#referenceBtn').onclick=()=>openReference();$('#fallbackRef').onclick=()=>openReference('layout');$$('[data-reference]').forEach(b=>b.onclick=()=>openReference(b.dataset.reference));$$('[data-ref-tab]').forEach(b=>b.onclick=()=>openReference(b.dataset.refTab));$('#helpBtn').onclick=()=>$('#helpDialog').showModal();$$('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
